async function c(r){try{const t=(await chrome.storage.local.get(["exness_errors"])).exness_errors||[];t.unshift({timestamp:Date.now(),message:r}),t.length>50&&(t.length=50),await chrome.storage.local.set({exness_errors:t})}catch(s){console.error("Failed to log error:",s)}}chrome.runtime.onMessage.addListener((r,s,t)=>{if(r.action==="fetchData")return i(r.url,"GET",r.token).then(e=>t({success:!0,data:e})).catch(e=>{c(`Fetch error: ${e.toString()}`),t({success:!1,error:e.toString()})}),!0;if(r.action==="sendRequest")return i(r.url,r.method,r.token,r.body,r.extraHeaders).then(e=>t({success:!0,data:e})).catch(e=>{c(`Request error (${r.method}): ${e.toString()}`),t({success:!1,error:e.toString()})}),!0;if(r.action==="logError")return c(r.message),t({success:!0}),!0;if(r.action==="getErrors")return chrome.storage.local.get(["exness_errors"]).then(e=>{t({success:!0,errors:e.exness_errors||[]})}),!0;if(r.action==="clearErrors")return chrome.storage.local.set({exness_errors:[]}).then(()=>{t({success:!0})}),!0});async function i(r,s="GET",t,e=null,u={}){try{const a={Accept:"application/json, text/plain, */*",Authorization:"Bearer "+t,"Content-Type":"application/json",...u},n={method:s,headers:a};e&&(n.body=JSON.stringify(e));const o=await fetch(r,n);if(!o.ok){const l=await o.text();throw new Error(`HTTP ${o.status}: ${l||o.statusText}`)}return o.status===204?{}:await o.json()}catch(a){throw console.error("Background request error:",a),a}}
